use crate::aap::caps::{http_client, state_read};

struct Node;

/// Keys the subscription list may be stored under in the 'subscriptions' store.
/// `state-read` cannot enumerate keys, so the candidates are tried in order.
const KEYS: [&str; 4] = ["urls", "subscriptions", "feeds", "list"];

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a query-string value (RFC 3986 unreserved set kept as is).
fn encode_query(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~') {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0f) as usize] as char);
        }
    }
    out
}

/// Collect the string elements of a JSON document, skipping object keys.
fn parse_json_strings(src: &str) -> Vec<String> {
    let chars: Vec<char> = src.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] != '"' {
            i += 1;
            continue;
        }
        i += 1;
        let mut s = String::new();
        while i < chars.len() && chars[i] != '"' {
            if chars[i] == '\\' && i + 1 < chars.len() {
                i += 1;
                match chars[i] {
                    'n' => s.push('\n'),
                    't' => s.push('\t'),
                    'r' => s.push('\r'),
                    'b' => s.push('\u{8}'),
                    'f' => s.push('\u{c}'),
                    'u' => {
                        let mut code: u32 = 0;
                        let mut n = 0;
                        while n < 4 && i + 1 < chars.len() {
                            match chars[i + 1].to_digit(16) {
                                Some(d) => {
                                    code = code * 16 + d;
                                    i += 1;
                                    n += 1;
                                }
                                None => break,
                            }
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                    }
                    other => s.push(other),
                }
            } else {
                s.push(chars[i]);
            }
            i += 1;
        }
        i += 1; // closing quote
        let mut j = i;
        while j < chars.len() && chars[j].is_whitespace() {
            j += 1;
        }
        let is_key = j < chars.len() && chars[j] == ':';
        if !is_key {
            out.push(s);
        }
    }
    out
}

/// Parse a stored value: either a JSON array of strings, or plain text with one
/// URL per line (commas and other whitespace also separate; `#` starts a comment).
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') || trimmed.starts_with('{') {
        parse_json_strings(trimmed)
    } else {
        let mut v = Vec::new();
        for line in trimmed.lines() {
            let line = match line.find('#') {
                // Only treat '#' as a comment at line start or after whitespace,
                // so URL fragments survive.
                Some(0) => "",
                Some(p) if line[..p].ends_with(char::is_whitespace) => &line[..p],
                _ => line,
            };
            for part in line.split(|c: char| c == ',' || c == ';' || c.is_whitespace()) {
                v.push(part.to_string());
            }
        }
        v
    };

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Requested enrichment call. `run-info` has no `text` field, so the
        // date (its only textual field) is the query. `fetch` is used so a
        // transport failure is a value, and the result is deliberately
        // discarded: the node's output does not depend on it.
        let url = format!("{}{}", ENRICH_ENDPOINT, encode_query(&info.date));
        let _ = http_client::fetch(&url);

        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        if urls.is_empty() {
            // `ensures present(urls)` cannot be met and a subscription must not
            // be invented: fail the node rather than emit a violating output.
            panic!("no subscriptions found in the 'subscriptions' store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
